def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'D'
    if n == 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = opp.count('D')
    opp_c = n - opp_d
    my_d = me.count('D')
    last_me = me[-1]
    last_opp = opp[-1]

    # If opponent has never defected, exploit
    if opp_d == 0:
        if my_d >= 2:
            return 'D'
        if last_me == 'D':
            return 'C'
        return 'D'

    # Compute punishment rate
    punish_attempts = 0
    punish_count = 0
    for i in range(n - 1):
        if me[i] == 'D':
            punish_attempts += 1
            if opp[i+1] == 'D':
                punish_count += 1
    punish_rate = punish_count / punish_attempts if punish_attempts > 0 else 0.0

    # Opponent just defected
    if last_opp == 'D':
        if last_me == 'D':
            # mutual defection
            if opp_c == 0:
                return 'D'
            dd_streak = 0
            for i in range(n - 1, -1, -1):
                if me[i] == 'D' and opp[i] == 'D':
                    dd_streak += 1
                else:
                    break
            if dd_streak >= 2:
                if rng.random() < 0.7:
                    return 'C'
            return 'D'
        else:
            # we cooperated, they defected
            if n >= 2 and me[-2] == 'C':
                return 'D'
            return 'C'

    # Opponent just cooperated
    if last_me == 'D':
        if punish_rate > 0.5:
            return 'C'
        return 'D'
    else:
        if punish_attempts > 0 and punish_rate < 0.2 and opp_d <= 2:
            if rng.random() < 0.15:
                return 'D'
        return 'C'
